import os
import sys
from PyPDF2 import PdfReader

# Target citizenship for filtering
TARGET_CITIZENSHIP = "United States"

def extract_text_from_pdf(pdf_path):
    """Extract text from a PDF file"""
    try:
        with open(pdf_path, 'rb') as file:
            reader = PdfReader(file)
            text = ""
            for page in reader.pages:
                text += page.extract_text()
            return text
    except Exception as e:
        print(f"Error reading {pdf_path}: {str(e)}")
        return ""

def extract_name_from_resume(text):
    """Extract name from resume text (simplified approach)"""
    # Look for name near the beginning of the resume
    lines = text.split('\n')
    for i, line in enumerate(lines[:10]):  # Check first 10 lines
        line = line.strip()
        # Simple heuristic: look for lines with capitalized words that might be names
        if line and len(line.split()) >= 2 and len(line.split()) <= 4:
            # Check if it looks like a name (all alphabetic characters and spaces)
            if all(c.isalpha() or c.isspace() for c in line):
                # Additional check: make sure it's not a section header
                if not any(keyword in line.lower() for keyword in ['resume', 'curriculum', 'vitae', 'contact', 'information']):
                    return line
    return None

def check_citizenship(text, target_citizenship):
    """Check if the target citizenship is mentioned in the resume"""
    return target_citizenship.lower() in text.lower()

def filter_resumes_by_citizenship(resumes_dir, output_file, target_citizenship=TARGET_CITIZENSHIP):
    """Filter resumes by target citizenship and save candidate names to output file"""
    if not os.path.exists(resumes_dir):
        print(f"Resumes directory {resumes_dir} does not exist.")
        return

    pdf_files = [f for f in os.listdir(resumes_dir) if f.lower().endswith('.pdf')]

    if not pdf_files:
        print(f"No PDF files found in {resumes_dir}")
        return

    matched_candidates = []

    for pdf_file in pdf_files:
        pdf_path = os.path.join(resumes_dir, pdf_file)
        print(f"Processing {pdf_file}...")

        # Extract text from PDF
        text = extract_text_from_pdf(pdf_path)

        if text:
            # Check if target citizenship is mentioned
            if check_citizenship(text, target_citizenship):
                # Extract candidate name
                name = extract_name_from_resume(text)
                if name:
                    matched_candidates.append(name)
                    print(f"Found match: {name}")
                else:
                    print(f"Citizenship match found but name not extracted from {pdf_file}")
            else:
                print(f"No citizenship match in {pdf_file}")
        else:
            print(f"Could not extract text from {pdf_file}")

    # Write matched candidate names to output file
    with open(output_file, 'a') as f:
        for name in matched_candidates:
            f.write(name + '\n')

    print(f"Saved {len(matched_candidates)} candidates to {output_file}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python resume_filter.py <output_file>")
        sys.exit(1)

    output_file = sys.argv[1]
    resumes_dir = os.path.join(os.path.dirname(__file__), "resumes")

    filter_resumes_by_citizenship(resumes_dir, output_file)

